def canonical(value):
    # Produce a deterministic JSON string for any value, including None
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def normalize(record):
    # Ensure required fields exist and have correct types
    return {
        "key": record["key"],
        "node": record["node"],
        "clock": validate(record["clock"]),
        "value": record.get("value"),
        "deleted": bool(record.get("deleted", False)),
    }

def resolve(records):
    # Remove exact duplicates based on canonical representation
    unique = {}
    for row in records:
        record = normalize(row)
        unique[canonical(record)] = record
    versions = list(unique.values())

    # Determine the causal frontier: versions not strictly dominated by any other
    frontier = []
    for candidate in versions:
        dominated = False
        for other in versions:
            if other is candidate:
                continue
            # other dominates candidate if compare(other, candidate) == 1
            if compare(other["clock"], candidate["clock"]) == 1:
                dominated = True
                break
        if not dominated:
            frontier.append(candidate)

    # Choose the winner according to the policy:
    # 1. Prefer tombstones (deleted=True)
    # 2. Then lexicographically greatest node
    # 3. Then lexicographically greatest canonical JSON value
    def winner_key(row):
        return (
            row["deleted"],               # True > False, so tombstone wins
            row["node"],                  # lexicographic order
            canonical(row["value"]),     # deterministic string comparison
        )

    winner = max(frontier, key=winner_key)

    return {
        "key": winner["key"],
        "value": None if winner["deleted"] else winner["value"],
        "deleted": winner["deleted"],
        "clock": joined([row["clock"] for row in versions]),
